global.schema:
type TeamJournalState {
  title: String!
  entries: [JournalEntry!]!
}

type JournalEntry {
  id: ID!
  author: String!
  text: String!
  pinned: Boolean!
}

operations.schema:
input AddEntryInput {
  id: ID!
  text: String!
}

operations.reducer:
if (state.entries.some((entry) => entry.id === action.input.id)) {
  throw new DuplicateEntryError(`Entry ${action.input.id} already exists`);
}
state.entries.push({
  id: action.input.id,
  author: action.context?.signer?.user?.address ?? "anonymous",
  text: action.input.text,
  pinned: false,
});

const entry = state.entries.find((candidate) => candidate.id === action.input.id);
if (!entry) {
  throw new EntryNotFoundError(`No entry ${action.input.id}`);
}
entry.pinned = true;
